#[test]
fn variant_sets_match_known_answers() {
    let encoder = Encoder::new().unwrap_or_else(|e| panic!("{e}"));
    for &(payload, context, defaults, expected) in CASES {
        let techniques: &[Technique] = if defaults {
            context.default_techniques()
        } else {
            &Technique::ALL
        };
        let got = encoder
            .evade(payload, context, techniques)
            .unwrap_or_else(|e| panic!("{e}"));
        let got: Vec<(&str, &str)> = got
            .iter()
            .map(|v| (v.technique.as_str(), v.payload.as_str()))
            .collect();
        assert_eq!(
            got, expected,
            "{payload:?} in {context} (defaults: {defaults})"
        );
    }
}

#[test]
fn reversible_variants_reverse() {
    let encoder = Encoder::new().unwrap_or_else(|e| panic!("{e}"));
    for &(payload, context, _, _) in CASES {
        for variant in encoder
            .evade(payload, context, &Technique::ALL)
            .unwrap_or_else(|e| panic!("{e}"))
        {
            if variant.is_reversible() {
                assert_eq!(
                    encoder.reverse(&variant).as_deref(),
                    Ok(payload),
                    "{} of {payload:?}",
                    variant.technique
                );
            }
        }
    }
}
